/* ── SMZ Coaches V2 — Cards CSS ── */

/* ═══════════════════════════════════════════════════
   LOADING SCREEN — 3D Spinning Power Card
═══════════════════════════════════════════════════ */

.loader-screen {
  position: fixed;
  inset: 0;
  z-index: 9999;
  /* matches The Card Vault's painted blue/gold backdrop */
  background:
    radial-gradient(ellipse 86% 70% at 50% 55%, transparent 58%, rgba(0,0,0,0.38) 100%),
    linear-gradient(180deg, rgba(4,10,26,0.55) 0%, rgba(4,10,26,0.22) 32%, transparent 60%),
    url('../img/bg_photo.jpg'),
    linear-gradient(165deg, #0a2d78 0%, #062060 55%, #030f38 100%);
  background-size: auto, auto, cover, cover;
  background-position: center, center, center, center;
  background-repeat: no-repeat;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 28px;
  transition: opacity 0.8s ease;
}

.loader-screen.fade-out {
  opacity: 0;
  pointer-events: none;
}

.loader-scene {
  perspective: 1000px;
  -webkit-perspective: 1000px;
  width: min(260px, 72vw);
  height: min(370px, 102vw);
  border-radius: 18px;
  box-shadow:
    0 0 60px rgba(234, 179, 8, 0.35),
    0 0 120px rgba(59, 130, 246, 0.2),
    0 30px 80px rgba(0, 0, 0, 0.7);
  animation: cardGlow 2.5s ease-in-out infinite;
  animation-delay: 5.25s;
}

.loader-card {
  width: 100%;
  height: 100%;
  position: relative;
  transform-style: preserve-3d;
  -webkit-transform-style: preserve-3d;
  animation: cardReveal 9s cubic-bezier(0.25, 0.46, 0.45, 0.94) forwards;
  cursor: grab;
  user-select: none;
}

.loader-card.dragging {
  cursor: grabbing;
  animation: none !important;
}

.loader-card.floating {
  animation: cardFloat 3s ease-in-out infinite;
}

/* Same idle wobble, centered on 0deg instead of -180deg — used when
   the card is settled showing its BACK face (e.g. the card viewer,
   where either face can be the one left showing). Using .floating
   here would yank the rotation toward the front-facing angle while
   the back image is still visible, rendering it mirrored. */
.loader-card.floating-back {
  animation: cardFloatBack 3s ease-in-out infinite;
}

/*
  Turn effect — a REAL 3D rotateY (so the width narrows with true
  perspective foreshortening, not a linear squeeze — this is what makes
  it read as an actual spin instead of a pinch). The front/back images
  never rotate independently and never rely on backface-visibility
  (that's what broke in Safari before); they're just two flat, stacked
  layers that ride along with the same rotation and cross-fade opacity
  exactly when the card is edge-on and paper-thin, so the swap itself
  is invisible.
*/
@keyframes cardReveal {
  0%   { transform: scale(0.7) translateY(20px) rotateY(0deg); opacity: 0; }
  6%   { transform: scale(0.85) translateY(10px) rotateY(0deg); opacity: 1; }

  /* Linger on back — let the viewer take it in */
  22%  { transform: scale(1) translateY(0px) rotateY(0deg); opacity: 1; }

  /* Slow cinematic turn — edge-on right around here, where the
     image swap happens */
  44%  { transform: scale(1.02) rotateY(-90deg); }
  56%  { transform: scale(1.04) rotateY(-170deg); }

  /* Slight overshoot then settle on front */
  66%  { transform: scale(1.03) rotateY(-188deg); }
  74%  { transform: scale(1.01) rotateY(-176deg); }
  82%  { transform: scale(1.0) rotateY(-180deg); }

  /* Hold beautifully on front */
  100% { transform: scale(1.0) rotateY(-180deg); opacity: 1; }
}

/* Back is visible for the first half, front for the second — swapped
   right as the card crosses edge-on (~44%, rotateY -90deg), so the
   swap itself is never actually seen. */
@keyframes cardBackFade {
  0%, 42%   { opacity: 1; }
  46%, 100% { opacity: 0; }
}

@keyframes cardFrontFade {
  0%, 42%   { opacity: 0; }
  46%, 100% { opacity: 1; }
}

@keyframes cardGlow {
  0%, 100% {
    box-shadow:
      0 0 30px rgba(234, 179, 8, 0.4),
      0 0 60px rgba(59, 130, 246, 0.25),
      0 0 100px rgba(234, 179, 8, 0.15),
      0 30px 80px rgba(0, 0, 0, 0.7);
  }
  50% {
    box-shadow:
      0 0 50px rgba(234, 179, 8, 0.7),
      0 0 100px rgba(59, 130, 246, 0.4),
      0 0 140px rgba(234, 179, 8, 0.25),
      0 30px 80px rgba(0, 0, 0, 0.7);
  }
}

@keyframes cardFloat {
  /* Gentle wobble while idle, centered on -180deg (where the front
     face's own +180 counter-rotation lands it right-side up). Stays
     well inside the front's visible range the whole time. */
  0%,
  100% { transform: translateY(0px) rotateY(-180deg); }
  50%  { transform: translateY(-8px) rotateY(-174deg); }
}

@keyframes cardFloatBack {
  /* Same wobble, centered on 0deg — where the back face's own
     rotateY(0deg) counter-rotation lands it right-side up. */
  0%,
  100% { transform: translateY(0px) rotateY(0deg); }
  50%  { transform: translateY(-8px) rotateY(6deg); }
}

.loader-card-face {
  position: absolute;
  inset: 0;
  border-radius: 18px;
}

/* Each face carries its own fixed counter-rotation so that whichever
   one is opaque is always right-side up at that point in the turn —
   back is untouched (0deg) since it's shown near the start, front is
   pre-rotated 180deg so it lands right-side up once the card has
   turned all the way around to show it. No backface-visibility is
   used anywhere here; opacity alone controls which one is seen, so
   there's nothing for Safari's 3D rendering to get wrong. */
.loader-card-back {
  opacity: 1;
  transform: rotateY(0deg);
  animation: cardBackFade 9s cubic-bezier(0.25, 0.46, 0.45, 0.94) forwards;
}

.loader-card-front {
  opacity: 0;
  transform: rotateY(180deg);
  animation: cardFrontFade 9s cubic-bezier(0.25, 0.46, 0.45, 0.94) forwards;
}

.loader-card-front,
.loader-card-back {
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  border-radius: 18px;
}

/* Left/right edges — a slim physical edge (like a real card's paper
   thickness, not a chunky box). Positioned with real depth (translateZ)
   so they fold away correctly as the card turns in true 3D. */
.loader-card-edge {
  position: absolute;
  top: 0;
  width: 5px;
  height: 100%;
  background: linear-gradient(to bottom, #8a6f22, #d9b64a 45%, #8a6f22);
}

.loader-card-edge-left {
  left: 0;
  border-radius: 3px 0 0 3px;
  transform-origin: left center;
  transform: translateZ(2.5px) rotateY(90deg);
}

.loader-card-edge-right {
  right: 0;
  border-radius: 0 3px 3px 0;
  transform-origin: right center;
  transform: translateZ(-2.5px) rotateY(90deg);
}

/* Sheen — a soft highlight that sweeps across the card as it turns,
   for a bit of the glossy/premium feel instead of flat, matte art. */
.loader-card-sheen {
  position: absolute;
  inset: 0;
  border-radius: 18px;
  pointer-events: none;
  background: linear-gradient(115deg, transparent 42%, rgba(255, 255, 255, 0.4) 50%, transparent 58%);
  background-size: 260% 260%;
  mix-blend-mode: overlay;
  opacity: 0;
  animation: cardSheen 12s cubic-bezier(0.25, 0.46, 0.45, 0.94) forwards;
}

@keyframes cardSheen {
  0%, 18%   { background-position: 130% 0%; opacity: 0; }
  38%       { opacity: 0.9; }
  50%       { background-position: -10% 0%; opacity: 1; }
  70%       { opacity: 0.4; }
  86%, 100% { background-position: -50% 0%; opacity: 0; }
}

/* Loader text */
.loader-text {
  font-family: 'Bebas Neue', sans-serif;
  font-size: 16px;
  letter-spacing: 5px;
  color: rgba(234, 179, 8, 0.7);
  animation: pulse 2s ease-in-out infinite;
  text-align: center;
}

@keyframes pulse {
  0%, 100% { opacity: 0.3; }
  50%       { opacity: 1; }
}

.loader-skip {
  font-size: 12px;
  color: var(--text-faint);
  letter-spacing: 2px;
  cursor: pointer;
  transition: color 0.2s;
  background: none;
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 999px;
  padding: 8px 20px;
  font-family: var(--font-body);
}

.loader-skip:hover { color: var(--text-muted); border-color: rgba(255,255,255,0.2); }


/* ── Embedded card face images ── */
.loader-card-back {
  background-image: url("data:image/png;base64,");
}

/* ══════════════════════════════════════════════════════════════════
   Schools Page (Card Generator shell) — hero, action bar, school
   grid, and add-school tile. Uses design tokens from tokens.css.
   ══════════════════════════════════════════════════════════════════ */

.replay-cards-intro {
  all: unset;
  position: fixed;
  z-index: 40;
  top: calc(var(--nav-height) + 14px + env(safe-area-inset-top, 0px));
  right: 14px;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 14px 8px 11px;
  border-radius: 999px;
  cursor: pointer;
  background: linear-gradient(160deg, #16233d 0%, #0a1220 100%);
  border: 1.5px solid #d9ae63;
  color: #f5e2ae;
  font-family: var(--font-body);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.04em;
  box-shadow: 0 8px 18px -8px rgba(0,0,0,0.75), inset 0 1px 0 rgba(255,255,255,0.08);
  transition: transform 0.18s ease, background 0.18s ease, box-shadow 0.18s ease;
}
.replay-cards-intro svg { flex: none; display: block; }
.replay-cards-intro:hover {
  transform: translateY(-1px);
  background: linear-gradient(160deg, #1c2c4a 0%, #0d1626 100%);
  box-shadow: 0 10px 22px -8px rgba(0,0,0,0.8), 0 0 16px -2px rgba(232,184,75,0.45), inset 0 1px 0 rgba(255,255,255,0.1);
}
@media (prefers-reduced-motion: reduce) {
  .replay-cards-intro { transition: none; }
}
@media (max-width: 600px) {
  .replay-cards-intro span { display: none; }
  .replay-cards-intro { padding: 9px; }
}

.cards-hero {
  position: relative;
  overflow: hidden;
  border: 1px solid var(--border);
  background: var(--surface-card);
  border-radius: var(--radius-lg);
  padding: var(--space-8) var(--space-8) var(--space-6);
  margin-bottom: var(--space-6);
}

.cards-hero::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: linear-gradient(90deg, var(--brand-gold), #f5d67a, var(--brand-gold));
}

.cards-hero-title {
  font-family: var(--font-display);
  font-size: clamp(34px, 6vw, 54px);
  letter-spacing: 3px;
  line-height: 1;
  color: var(--text-primary);
  margin-bottom: var(--space-3);
}

.cards-hero-sub {
  color: var(--text-muted);
  font-size: 15px;
  line-height: 1.6;
  max-width: 520px;
}

.cards-action-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
  margin-bottom: var(--space-5);
  flex-wrap: wrap;
}

.schools-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: var(--space-5);
}

.school-card {
  background: var(--surface-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  cursor: pointer;
  transition: all var(--transition-base);
}

.school-card:hover {
  background: var(--surface-card-hover);
  border-color: var(--border-strong);
  transform: translateY(-3px);
  box-shadow: var(--shadow-card-hover);
}

.school-card-bar {
  height: 5px;
  background: linear-gradient(90deg, var(--brand-green), var(--brand-gold));
}

.school-card-body {
  padding: var(--space-5);
}

.school-card-name {
  font-family: var(--font-display);
  font-size: 22px;
  letter-spacing: 1px;
  color: var(--text-primary);
  line-height: 1.15;
  margin-bottom: var(--space-2);
  word-break: break-word;
}

.school-card-meta {
  font-size: 13px;
  color: var(--text-muted);
}

.add-school-btn {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--space-3);
  width: 100%;
  min-height: 160px;
  background: rgba(255, 255, 255, 0.02);
  border: 2px dashed var(--border-strong);
  border-radius: var(--radius-lg);
  color: var(--text-muted);
  font-family: var(--font-body);
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  text-align: center;
  padding: var(--space-6);
  transition: all var(--transition-fast);
}

.add-school-btn:hover {
  border-color: var(--brand-green);
  color: var(--brand-green);
  background: rgba(121, 183, 44, 0.08);
}

.add-school-icon {
  font-size: 32px;
  line-height: 1;
  opacity: 0.6;
}

/* ══════════════════════════════════════════════════════════════════
   Roster, Player Profile, Participation Log, Records — Card
   Generator M2/M3 supporting UI. Uses design tokens from tokens.css.
   ══════════════════════════════════════════════════════════════════ */

/* ── Roster list ── */
.roster-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.roster-row {
  display: flex;
  align-items: center;
  gap: var(--space-4);
  background: var(--surface-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: var(--space-3) var(--space-4);
  cursor: pointer;
  transition: all var(--transition-fast);
}

.roster-row:hover {
  background: var(--surface-card-hover);
  border-color: var(--border-strong);
  transform: translateX(2px);
}

.roster-avatar {
  flex-shrink: 0;
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background-color: var(--ink-light);
  background-size: cover;
  background-position: center;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-display);
  font-size: 16px;
  letter-spacing: 1px;
  color: var(--text-muted);
  border: 2px solid var(--border-strong);
}

.roster-info {
  flex: 1;
  min-width: 0;
}

.roster-name {
  font-family: var(--font-body);
  font-weight: 600;
  font-size: 15px;
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.roster-meta {
  font-size: 12px;
  color: var(--text-muted);
  margin-top: 2px;
}

.roster-delete {
  flex-shrink: 0;
  background: transparent;
  border: 1px solid var(--border);
  color: var(--text-faint);
  border-radius: var(--radius-sm);
  width: 32px;
  height: 32px;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.roster-delete:hover {
  color: var(--crystal-safety);
  border-color: var(--crystal-safety);
}

/* ── Player profile header ── */
.profile-header {
  display: flex;
  align-items: center;
  gap: var(--space-4);
  flex-wrap: wrap;
  background: var(--surface-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: var(--space-5);
  margin-bottom: var(--space-6);
}

.profile-avatar {
  flex-shrink: 0;
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background-color: var(--ink-light);
  background-size: cover;
  background-position: center;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-display);
  font-size: 22px;
  letter-spacing: 1px;
  color: var(--text-muted);
  border: 2px solid var(--brand-gold);
}

.profile-header-info {
  flex: 1;
  min-width: 160px;
}

.profile-name {
  font-family: var(--font-display);
  font-size: 26px;
  letter-spacing: 1px;
  color: var(--text-primary);
  line-height: 1.1;
}

.profile-meta {
  font-size: 13px;
  color: var(--text-muted);
  margin-top: 4px;
}

.profile-generate-btn {
  white-space: nowrap;
}

/* ── Profile two-column layout ── */
.profile-layout {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: var(--space-6);
  align-items: start;
}

@media (max-width: 720px) {
  .profile-layout {
    grid-template-columns: 1fr;
  }
}

/* ── Participation sidebar ── */
.participation-sidebar {
  background: var(--surface-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: var(--space-4);
}

.participation-empty {
  font-size: 13px;
  color: var(--text-faint);
  line-height: 1.5;
  padding: var(--space-3) 0;
}

.participation-item {
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: var(--space-3);
  margin-bottom: var(--space-2);
}

.participation-item-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 4px;
}

.participation-type {
  display: inline-block;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  padding: 3px 8px;
  border-radius: var(--radius-pill);
}

.participation-type-camp {
  background: rgba(34, 197, 94, 0.18);
  color: #4ade80;
}

.participation-type-after-school {
  background: rgba(59, 130, 246, 0.18);
  color: #60a5fa;
}

.participation-type-birthday-party {
  background: rgba(234, 179, 8, 0.18);
  color: #facc15;
}

.participation-label {
  font-size: 13px;
  color: var(--text-primary);
  margin-bottom: 2px;
}

.participation-date {
  font-size: 11px;
  color: var(--text-faint);
}

.participation-delete {
  background: transparent;
  border: none;
  color: var(--text-faint);
  cursor: pointer;
  font-size: 12px;
  padding: 2px 4px;
  transition: color var(--transition-fast);
}

.participation-delete:hover {
  color: var(--crystal-safety);
}

/* ── Records panel (Super Moverz Records) ── */
.records-panel {
  background: var(--surface-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: var(--space-4);
}

.records-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: var(--space-4);
  margin-top: var(--space-3);
}

.record-card {
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  overflow: hidden;
}

.record-card-photo {
  width: 100%;
  aspect-ratio: 3 / 4;
  background-color: var(--ink-light);
  background-size: cover;
  background-position: center;
}

.record-card-body {
  padding: var(--space-3);
}

.record-card-title {
  font-family: var(--font-display);
  font-size: 15px;
  letter-spacing: 0.5px;
  color: var(--brand-gold);
}

.record-card-meta {
  font-size: 11px;
  color: var(--text-muted);
  margin-top: 2px;
}

/* ── Photo upload (Add Player modal) ── */
.photo-upload-row {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

.photo-upload-preview {
  flex-shrink: 0;
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background-color: var(--ink-light);
  background-size: cover;
  background-position: center;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
  border: 2px dashed var(--border-strong);
}

.photo-upload-label {
  cursor: pointer;
}

/* ══════════════════════════════════════════════════════════════════
   Archive / Move UI — collapsible archived sections, badges, and
   the "Move to Class" modal / enrollment history list.
   ══════════════════════════════════════════════════════════════════ */

.archived-section {
  margin-top: var(--space-6);
}

.archived-section summary {
  cursor: pointer;
  list-style: none;
  font-family: var(--font-body);
  font-size: 13px;
  font-weight: 600;
  color: var(--text-muted);
  padding: var(--space-3) var(--space-4);
  background: rgba(255, 255, 255, 0.02);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
}

.archived-section summary::-webkit-details-marker {
  display: none;
}

.archived-section summary::before {
  content: '▸ ';
  color: var(--text-faint);
}

.archived-section[open] summary::before {
  content: '▾ ';
}

.archived-section summary:hover {
  color: var(--text-primary);
  border-color: var(--border-strong);
}

.is-archived {
  opacity: 0.68;
}

.archived-badge {
  display: inline-block;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  color: var(--text-faint);
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid var(--border);
  border-radius: var(--radius-pill);
  padding: 2px 8px;
  vertical-align: middle;
}

.archived-note {
  color: var(--text-faint);
  font-size: 11px;
}

/* ── Profile header actions ── */
.profile-actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

/* ── Enrollment history (profile sidebar) ── */
.enrollment-log {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}

.enrollment-log-item {
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid var(--border);
  border-left: 3px solid var(--brand-green);
  border-radius: var(--radius-sm);
  padding: var(--space-2) var(--space-3);
}

.enrollment-log-class {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
}

.enrollment-log-school {
  font-size: 11px;
  color: var(--text-faint);
  margin-top: 2px;
}

/* ── Modal hint text ── */
.modal-hint {
  font-size: 13px;
  color: var(--text-muted);
  line-height: 1.5;
  margin-bottom: var(--space-3);
}

/* ══════════════════════════════════════════════════════════════════
   Card Creator Wizard — photo upload/positioning, age group picker,
   score grid, shield display, and the live canvas preview.
   ══════════════════════════════════════════════════════════════════ */

.card-creator-layout {
  display: grid;
  grid-template-columns: minmax(280px, 380px) 1fr;
  gap: var(--space-6);
  align-items: start;
}

@media (max-width: 760px) {
  .card-creator-layout {
    grid-template-columns: 1fr;
  }
}

.card-creator-form {
  display: flex;
  flex-direction: column;
  gap: var(--space-5);
}

.creator-field {
  background: var(--surface-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: var(--space-4);
}

.creator-field-disabled {
  opacity: 0.5;
}

/* Reuses the .fl label style pattern from the old proven tool */
.creator-field .fl {
  font-size: 10px;
  font-weight: 700;
  color: var(--text-faint);
  text-transform: uppercase;
  letter-spacing: 1.5px;
  margin-bottom: var(--space-3);
}

/* ── Photo upload ── */
.creator-photo-drop {
  width: 100%;
  aspect-ratio: 4 / 3;
  background: rgba(255, 255, 255, 0.02);
  border: 2px dashed var(--border-strong);
  border-radius: var(--radius-md);
  cursor: pointer;
  overflow: hidden;
  position: relative;
  transition: border-color var(--transition-fast);
}

.creator-photo-drop:hover {
  border-color: var(--brand-gold);
}

.creator-photo-drop img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.creator-photo-placeholder {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  color: var(--text-faint);
  font-size: 12px;
}

.creator-photo-placeholder span {
  font-size: 26px;
}

/* ── Position/zoom sliders ── */
.creator-slider-row {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  margin-bottom: 6px;
}

.creator-slider-row:last-child {
  margin-bottom: 0;
}

.creator-slider-label {
  width: 36px;
  font-size: 11px;
  color: var(--text-muted);
  flex-shrink: 0;
}

.creator-slider-row input[type="range"] {
  flex: 1;
  accent-color: var(--brand-gold);
}

.creator-slider-value {
  width: 34px;
  text-align: right;
  font-size: 11px;
  color: var(--brand-gold);
  flex-shrink: 0;
}

/* ── Age group picker ── */
.creator-group-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-2);
}

.creator-group-btn {
  background: rgba(255, 255, 255, 0.02);
  border: 1.5px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 8px 6px;
  min-height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.creator-group-btn:hover {
  border-color: rgba(234, 179, 8, 0.4);
}

.creator-group-btn.selected {
  border-color: var(--brand-gold);
  background: rgba(234, 179, 8, 0.1);
}

.creator-group-btn img {
  max-width: 100%;
  max-height: 28px;
  object-fit: contain;
}

/* ── Card style (tier) grid ── */
.creator-tier-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--space-2);
}

.creator-tier-btn {
  background: rgba(255, 255, 255, 0.02);
  border: 1.5px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 4px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.creator-tier-btn:hover {
  border-color: rgba(234, 179, 8, 0.4);
}

.creator-tier-btn.selected {
  border-color: var(--brand-gold);
  background: rgba(234, 179, 8, 0.1);
}

.creator-tier-btn img {
  width: 100%;
  aspect-ratio: 750 / 1050;
  object-fit: cover;
  border-radius: 3px;
}

.creator-tier-btn span {
  font-size: 10px;
  line-height: 1.1;
  text-align: center;
  color: var(--text-secondary);
}

.creator-tier-btn.selected span {
  color: var(--brand-gold);
}

/* ── Score grid ── */
.creator-score-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: var(--space-2);
}

.creator-score-col {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
}

.creator-score-label {
  font-size: 8px;
  font-weight: 700;
  text-transform: uppercase;
  color: var(--text-faint);
  text-align: center;
  line-height: 1.2;
}

.creator-score-icons {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.creator-score-icon {
  width: 30px;
  height: 30px;
  border-radius: 6px;
  border: 1.5px solid var(--border);
  background: rgba(0, 0, 0, 0.2);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0.3;
  transition: all var(--transition-fast);
}

.creator-score-icon.on {
  opacity: 1;
  border-color: rgba(234, 179, 8, 0.5);
}

.creator-score-icon img {
  width: 22px;
  height: 22px;
  object-fit: contain;
}

/* ── Shield display ── */
.creator-shield-display {
  text-align: center;
}

.creator-shield-count {
  font-size: 12px;
  color: var(--text-muted);
  margin-bottom: var(--space-2);
}

.creator-shield-count strong {
  color: var(--brand-gold);
}

.creator-shield-row {
  display: flex;
  gap: 6px;
  justify-content: center;
}

.creator-shield-row img {
  width: 26px;
  height: 26px;
  object-fit: contain;
}

.creator-shield-row img.dim {
  opacity: 0.15;
}

/* ── Live canvas preview ── */
.card-creator-preview {
  display: flex;
  justify-content: center;
  position: sticky;
  top: var(--space-4);
}

.creator-canvas-wrap {
  background: #060810;
  border-radius: var(--radius-md);
  padding: var(--space-5);
  display: flex;
  align-items: center;
  justify-content: center;
}

#creator-canvas {
  display: block;
  border-radius: 6px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.6);
  max-width: 100%;
  height: auto;
}

/* Records grid entries are clickable once the 3D viewer exists */
.record-card {
  cursor: pointer;
  transition: transform var(--transition-fast), border-color var(--transition-fast);
}

.record-card:hover {
  transform: translateY(-2px);
  border-color: var(--border-strong);
}

/* ══════════════════════════════════════════════════════════════════
   3D Card Viewer — closable overlay reusing the loader's drag-to-
   rotate flip visuals (.loader-scene / .loader-card / .loader-card-
   face) to view one saved Power Card front-to-back.
   ══════════════════════════════════════════════════════════════════ */

.card-viewer-overlay {
  position: fixed;
  inset: 0;
  z-index: 3000;
  background: rgba(5, 10, 20, 0.92);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  display: flex;
  align-items: center;
  justify-content: center;
}

.card-viewer-close {
  position: absolute;
  top: var(--space-5);
  right: var(--space-5);
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid var(--border-strong);
  color: var(--text-primary);
  font-size: 18px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-fast);
  z-index: 3001;
}

.card-viewer-close:hover {
  background: rgba(255, 255, 255, 0.15);
  border-color: var(--brand-gold);
}

/* ══════════════════════════════════════════════════════════════════
   Card Creator — Background removal toggle (Original / Remove BG)
   ══════════════════════════════════════════════════════════════════ */

.creator-bg-row {
  display: flex;
  gap: 6px;
  margin-top: 8px;
}

.creator-bg-btn {
  flex: 1;
  padding: 7px 8px;
  border-radius: var(--radius-sm);
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
  transition: all var(--transition-fast);
  text-align: center;
  letter-spacing: 0.3px;
  background: transparent;
  color: var(--text-muted);
  border: 1.5px solid var(--border);
}

.creator-bg-btn:hover {
  border-color: var(--border-strong);
  color: var(--text-primary);
}

.creator-bg-btn.active {
  color: var(--brand-gold);
  border-color: var(--brand-gold);
  background: rgba(234, 179, 8, 0.1);
}

.creator-bg-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.creator-bg-status {
  font-size: 11px;
  color: var(--text-muted);
  margin-top: 6px;
  text-align: center;
  min-height: 14px;
  line-height: 1.4;
}

/* ── Scoring Guide ─────────────────────────────────────────────── */
.fl-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}
.scoring-guide-btn {
  width: 22px;
  height: 22px;
  flex-shrink: 0;
  border-radius: 50%;
  border: 1.5px solid var(--brand-gold);
  background: rgba(234, 179, 8, 0.1);
  color: var(--brand-gold);
  font-family: var(--font-body);
  font-weight: 700;
  font-size: 12px;
  line-height: 1;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-fast);
}
.scoring-guide-btn:hover {
  background: rgba(234, 179, 8, 0.2);
  transform: scale(1.08);
}

.scoring-guide-overlay {
  position: fixed;
  inset: 0;
  background: rgba(6, 10, 18, 0.92);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  z-index: 999;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 24px 16px;
  overflow-y: auto;
}
.scoring-guide-panel {
  background: var(--surface);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-lg);
  max-width: 480px;
  width: 100%;
  padding: 28px 22px 24px;
  position: relative;
  box-shadow: var(--shadow-card-hover);
  margin: auto;
}
.scoring-guide-close {
  position: absolute;
  top: 14px;
  right: 14px;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  border: 1px solid var(--border-strong);
  background: rgba(255, 255, 255, 0.06);
  color: var(--text-primary);
  font-size: 15px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-fast);
}
.scoring-guide-close:hover {
  background: rgba(255, 255, 255, 0.14);
}
.scoring-guide-header {
  text-align: center;
  margin-bottom: 22px;
}
.scoring-guide-logo {
  width: 48px;
  height: 48px;
  object-fit: contain;
  margin-bottom: 6px;
}
.scoring-guide-title {
  font-family: var(--font-display);
  font-size: 26px;
  letter-spacing: 1.5px;
  color: var(--brand-gold);
}
.scoring-guide-sub {
  font-family: var(--font-body);
  font-size: 13px;
  color: var(--text-muted);
  margin-top: 6px;
  line-height: 1.5;
}
.scoring-guide-rows {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.scoring-guide-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  border-radius: var(--radius-md);
  background: var(--row-bg);
  border: 1px solid var(--row-border);
}
.scoring-guide-icons {
  display: flex;
  gap: 3px;
  flex-shrink: 0;
}
.scoring-guide-icons img {
  width: 26px;
  height: 26px;
  object-fit: contain;
}
.scoring-guide-info {
  min-width: 0;
}
.scoring-guide-label {
  font-family: var(--font-display);
  font-size: 16px;
  letter-spacing: 0.5px;
  color: var(--text-primary);
}
.scoring-guide-blurb {
  font-family: var(--font-body);
  font-size: 12px;
  color: var(--text-muted);
  line-height: 1.4;
  margin-top: 2px;
}
.scoring-guide-divider {
  height: 1px;
  background: var(--border);
  margin: 20px 0;
}
.scoring-guide-shields {
  text-align: center;
}
.scoring-guide-shields-title {
  font-family: var(--font-display);
  font-size: 18px;
  letter-spacing: 1px;
  color: var(--brand-gold);
  margin-bottom: 10px;
}
.scoring-guide-shields-row {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-bottom: 10px;
}
.scoring-guide-shields-row img {
  width: 34px;
  height: 34px;
  object-fit: contain;
}
.scoring-guide-shields-note {
  font-family: var(--font-body);
  font-size: 12px;
  color: var(--text-muted);
  line-height: 1.5;
  max-width: 360px;
  margin: 0 auto;
}
